// A source withdrawal invalidates dependent report versions, not the claim itself.
export function withdrawSource(state: MobileState): MobileState {
  if (state.withdrawn) return state;
  return {
    ...state,
    withdrawn: true,
    collaboration:
      state.collaboration.phase === "published"
        ? { ...state.collaboration, phase: "changed" }
        : state.collaboration,
    reports: state.reports.map((r) => ({
      ...r,
      stale: r.stale || r.evidenceIds.includes(controlledDocument),
    })),
  };
}

