// Rebuild against available evidence; human approval is required again for the new version.
export function rebuildReport(state: MobileState, id: string): MobileState {
  return {
    ...state,
    reports: state.reports.map((r) =>
      r.id === id
        ? {
            ...r,
            revision: r.revision + 1,
            status: "待审核",
            stale: false,
            evidenceIds: reportDocuments(r.scope, state.withdrawn).map(
              (a) => a.id,
            ),
          }
        : r,
    ),
  };
}

// Guard the same publication conditions regardless of which screen invokes approval.
export function approveReport(
  state: MobileState,
  id: string,
  checked: boolean,
): MobileState {
  return {
    ...state,
    reports: state.reports.map((r) =>
      r.id === id && checked && !r.stale && r.status === "待审核"
        ? { ...r, status: "已发布" }
        : r,
    ),
  };
}

// Keep the risk status and the human decision log in a single state transition.
export function submitReview(
  state: MobileState,
  riskId: string,
  result: ReviewResult,
  note: string,
  time: string,
): MobileState {
  if (
    note.trim().length < 5 ||
    !initialRisks.some((r) => r.id === riskId) ||
    !["通过复核", "补充材料", "排除线索"].includes(result)
  )
    return state;
  return {
    ...state,
    statuses: {
      ...state.statuses,
      [riskId]:
        result === "通过复核"
          ? "已确认"
          : result === "排除线索"
            ? "已归档"
            : "复核中",
    },
    reviews: [{ riskId, result, note: note.trim(), time }, ...state.reviews],
  };
}
